llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Artemisinin, a polycyclic oxygenated natural product with lactone and ether groups, is reported to have low oral bioavailability in humans, supporting a low F prediction for the similarly polar, rigid oxygen-rich scaffold of the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Oral artemisinin absorption is variable with low bioavailability in healthy volunteers and malaria patients, consistent with poor oral exposure for neutral polycyclic lactone-type molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Artesunate, an artemisinin derivative, showed 61% absolute oral bioavailability in Thai patients, indicating that some oxygen-rich polycyclic scaffolds can achieve F≥20%; however, artesunate is an ionizable prodrug ester, unlike the neutral query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C25"],
      "claim": "Omadacycline, a highly polar polyfunctional molecule, achieved 34.5% oral bioavailability in healthy adults, showing that high polarity alone does not preclude F≥20%; however, it is ionizable and structurally unrelated to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a neutral, rigid, highly polar polycyclic lactone (PSA 169 Å², logD -2.4, 11 HBA). The closest experimental analogue, artemisinin, is consistently reported to have low/poor oral bioavailability, and the query's even higher polarity and H-bonding capacity make F≥20% unlikely. High-F records for artesunate, omadacycline, and rosaramicin are less transferable because they involve ionizable prodrugs or structurally unrelated scaffolds. Therefore, low is predicted.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query or a close triptolide-like analogue.",
    "Artemisinin records are for a different scaffold (endoperoxide sesquiterpene lactone) and may not fully transfer.",
    "No permeability, transporter, or first-pass metabolism data for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

